const NAV=[{id:'today',name:'Сегодня',icon:Sun},{id:'quran',name:'Коран',icon:BookOpen},{id:'adhkar',name:'Азкары',icon:Sparkles},{id:'qibla',name:'Кибла',icon:Compass},{id:'settings',name:'Настройки',icon:Settings2}];
