function stored<T>(k:string,f:T):T{try{return JSON.parse(localStorage.getItem(k)||'null')??f;}catch{return f;}}
function save(k:string,v:unknown){try{localStorage.setItem(k,JSON.stringify(v));}catch{}}
function download(text:string,name:string,type:string){const u=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}

export default function App(){
const [view,setView]=useState<View>('today'),[place,setPlace]=useState<Place>(DEFAULT_PLACE),[settings,setSettings]=useState<Settings>(DEFAULT_SETTINGS),[ready,setReady]=useState(false),[now,setNow]=useState(new Date()),[selectedDay,setSelectedDay]=useState('');
const [modal,setModal]=useState(''),[toast,setToast]=useState(''),[online,setOnline]=useState(true),[arabic,setArabic]=useState<Surah[]>([]),[russian,setRussian]=useState<Surah[]>([]),[dataError,setDataError]=useState(''),[loading,setLoading]=useState(false);
const [surah,setSurah]=useState<number|null>(null),[mode,setMode]=useState('translation'),[page,setPage]=useState(1),[pageInput,setPageInput]=useState('1'),[query,setQuery]=useState(''),[position,setPosition]=useState<{surah:number;ayah:number;page:number}|null>(null),[bookmarks,setBookmarks]=useState<string[]>([]),[bookError,setBookError]=useState(false),[bookLoading,setBookLoading]=useState(true),[downloadBusy,setDownloadBusy]=useState(false),[cacheStatus,setCacheStatus]=useState('');
const [group,setGroup]=useState('morning'),[afterPrayer,setAfterPrayer]=useState('Dhuhr'),[counts,setCounts]=useState<Record<string,number>>({}),[dailyKey,setDailyKey]=useState(''),[expanded,setExpanded]=useState<string|null>(null);
const [heading,setHeading]=useState<number|null>(null),[compassStatus,setCompassStatus]=useState(''),[playing,setPlaying]=useState(false),[playingSurah,setPlayingSurah]=useState<number|null>(null),[audioError,setAudioError]=useState('');
const [notificationEnabled,setNotificationEnabled]=useState(false),[permission,setPermission]=useState('default'),[pushInfo,setPushInfo]=useState<{configured:boolean;scheduler:boolean}|null>(null),[pushStatus,setPushStatus]=useState('');
const [locationQuery,setLocationQuery]=useState(''),[locationResults,setLocationResults]=useState<Place[]>([]),[locationBusy,setLocationBusy]=useState(false),[locationError,setLocationError]=useState(''),[coordinates,setCoordinates]=useState({latitude:'',longitude:'',timezone:'Europe/Moscow'});
const audio=useRef<HTMLAudioElement|null>(null),installPrompt=useRef<any>(null),notified=useRef(new Set<string>()),compassCleanup=useRef<(()=>void)|null>(null),loadingRef=useRef(false);
const notify=(text:string)=>setToast(text);
useEffect(()=>{if(!modal)return;const previous=document.activeElement as HTMLElement|null,overflow=document.body.style.overflow;document.body.style.overflow='hidden';const dialog=document.querySelector<HTMLElement>('.modal');const focusable=()=>Array.from(dialog?.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),select,a[href],summary')||[]).filter(el=>el.offsetParent!==null);focusable()[0]?.focus();const keys=(e:KeyboardEvent)=>{if(e.key==='Escape')setModal('');if(e.key==='Tab'){const all=focusable(),first=all[0],last=all[all.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}};document.addEventListener('keydown',keys);return()=>{document.body.style.overflow=overflow;document.removeEventListener('keydown',keys);previous?.isConnected&&previous.focus();};},[modal]);
useEffect(()=>{setPlace(stored('noor-place',DEFAULT_PLACE));setSettings({...DEFAULT_SETTINGS,...stored('noor-settings',{})});setPosition(stored('noor-position',null));setBookmarks(stored('noor-bookmarks',[]));setNotificationEnabled(stored('noor-notifications',false));setPermission('Notification'in window?Notification.permission:'unsupported');setOnline(navigator.onLine);setReady(true);const t=setInterval(()=>setNow(new Date()),1000);const on=()=>setOnline(true),off=()=>setOnline(false);window.addEventListener('online',on);window.addEventListener('offline',off);const hash=()=>{const h=location.hash.slice(1);if(NAV.some(n=>n.id===h)){setView(h as View);setSurah(null);}};hash();window.addEventListener('hashchange',hash);const inst=(e:Event)=>{e.preventDefault();installPrompt.current=e;};window.addEventListener('beforeinstallprompt',inst);if('serviceWorker'in navigator){if(process.env.NODE_ENV==='production')navigator.serviceWorker.register('/sw.js').catch(()=>{});else navigator.serviceWorker.getRegistrations().then(all=>all.forEach(r=>r.unregister()));}fetch('/api/push/status').then(r=>r.ok?r.json():null).then((d:any)=>setPushInfo(d)).catch(()=>{});return()=>{clearInterval(t);window.removeEventListener('online',on);window.removeEventListener('offline',off);window.removeEventListener('hashchange',hash);window.removeEventListener('beforeinstallprompt',inst);compassCleanup.current?.();audio.current?.pause();};},[]);
useEffect(()=>{if(ready){save('noor-place',place);save('noor-settings',settings);document.documentElement.dataset.theme=settings.theme;document.documentElement.dataset.glass=settings.reducedGlass?'reduced':'full';}},[place,settings,ready]);
useEffect(()=>{if(!toast)return;const t=setTimeout(()=>setToast(''),6000);return()=>clearTimeout(t);},[toast]);
const today=dayInZone(now,place.timezone),date=selectedDay||today;
useEffect(()=>{if(!ready)return;const key=`noor-dhikr-v2-${today}-${group}${group==='prayer'?'-'+afterPrayer:''}`;setDailyKey(key);setCounts(stored(key,{}));},[today,group,afterPrayer,ready]);
useEffect(()=>{if(dailyKey)save(dailyKey,counts);},[counts,dailyKey]);
const schedule=useMemo(()=>calculate(place,settings,date),[place,settings,date]);
const next=useMemo(()=>nextPrayer(place,settings,now),[place,settings,now]);
const seconds=Math.max(0,Math.floor(((next?.date.getTime()||0)-now.getTime())/1000));const countdown=[Math.floor(seconds/3600),Math.floor(seconds/60)%60,seconds%60].map(n=>String(n).padStart(2,'0')).join(':');
const bearing=useMemo(()=>qibla(place),[place]);const current=surah?arabic[surah-1]:null;
const pageMeta=useMemo(()=>arabic.flatMap(s=>s.ayahs.filter(a=>a.page===page).map(a=>({surah:s.number,name:s.name,...a}))),[arabic,page]);
const list=useMemo(()=>arabic.filter(s=>`${s.number} ${s.name} ${s.englishName} ${SURAH_NAMES[s.number-1]} ${SURAH_MEANINGS[s.number-1]}`.toLowerCase().includes(query.toLowerCase().trim())),[arabic,query]);
const dhikrs=group==='prayer'?getPrayerAdhkar(afterPrayer):ADHKAR_GROUPS[group as 'morning'|'evening'].map(id=>ADHKAR.find(d=>d.id===id)!),completed=dhikrs.filter(d=>(counts[d.id]||0)>=d.target).length;
const hijri=useMemo(()=>{try{return new Intl.DateTimeFormat('ru-RU-u-ca-islamic-umalqura',{timeZone:place.timezone,day:'numeric',month:'long',year:'numeric'}).format(now).replace(' г.','');}catch{return '';}},[today,place.timezone]);
const go=(id:View)=>{setView(id);setSurah(null);history.replaceState(null,'','#'+id);window.scrollTo(0,0);};
const update=(k:keyof Settings,v:any)=>setSettings(s=>({...s,[k]:v}));
async function loadQuran(){if(loadingRef.current||arabic.length)return;loadingRef.current=true;setLoading(true);setDataError('');try{const responses=await Promise.all([fetch('/data/arabic.json'),fetch('/data/russian.json')]);if(responses.some(r=>!r.ok))throw Error();const [a,r]:any[]=await Promise.all(responses.map(r=>r.json()));if(a.length!==114||r.length!==114)throw Error();setArabic(a);setRussian(r);}catch{setDataError('Не удалось открыть Коран. Проверьте подключение и попробуйте ещё раз.');}finally{loadingRef.current=false;setLoading(false);}}
useEffect(()=>{if(view==='quran'||view==='today')loadQuran();},[view]);
useEffect(()=>{setBookError(false);setBookLoading(true);setPageInput(String(page));},[page]);
useEffect(()=>{if(!ready||!notificationEnabled||permission!=='granted'||pushInfo?.configured&&pushInfo.scheduler)return;for(const p of [...calculate(place,settings,today),...calculate(place,settings,shiftDay(today,1))]){if(!settings.enabledPrayers.includes(p.id)||!Number.isFinite(p.date?.getTime()))continue;const time=p.date.getTime()-settings.reminder*60000,key=p.id+'-'+p.date.toISOString();if(time<=now.getTime()&&time>now.getTime()-1500&&!notified.current.has(key)){notified.current.add(key);navigator.serviceWorker.ready.then(reg=>reg.showNotification(`Нур · ${p.name}`,{body:`${place.name} · ${formatTime(p.date,place.timezone)}${settings.reminder?` · Через ${settings.reminder} мин.`:''}`,icon:'/icons/icon-192.png',tag:key,data:{url:'/#today'}})).catch(()=>{});}}},[now,notificationEnabled,permission,pushInfo,settings,place,today,ready]);
useEffect(()=>{if(!ready||!notificationEnabled||!pushInfo?.configured)return;const t=setTimeout(()=>syncPush(false),1500);return()=>clearTimeout(t);},[place,settings,notificationEnabled,pushInfo,ready]);
async function syncPush(create:boolean){try{const reg=await navigator.serviceWorker.ready;let subscription=await reg.pushManager.getSubscription();if(!subscription&&create){const {publicKey}:any=await fetch('/api/push/key').then(r=>r.json());const normalized=publicKey.replace(/-/g,'+').replace(/_/g,'/');const bytes=Uint8Array.from(atob(normalized),c=>c.charCodeAt(0));subscription=await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:bytes});}if(!subscription)return;const r=await fetch('/api/push/subscribe',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({subscription:subscription.toJSON(),place,settings})});if(!r.ok)throw Error();setPushStatus('Web Push подключён. Время и настройки синхронизированы.');}catch{setPushStatus('Не удалось подключить фоновые уведомления. Повторите попытку.');}}
async function testNotification(){try{if(pushInfo?.configured){const reg=await navigator.serviceWorker.ready;const sub=await reg.pushManager.getSubscription();if(sub){const r=await fetch('/api/push/test',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({endpoint:sub.endpoint})});if(r.ok){notify('Сервер отправил тестовое push-уведомление');return;}}}const r=await navigator.serviceWorker.ready;await r.showNotification('Нур · Уведомления работают',{body:`${place.name}. Время для главного — всегда рядом.`,icon:'/icons/icon-192.png',tag:'noor-test',data:{url:'/#today'}});notify('Тестовое уведомление отправлено');}catch{notify('Сначала разрешите уведомления на этом устройстве.');}}
async function enableNotifications(){if(!('Notification'in window)||!('serviceWorker'in navigator)){notify('На iPhone установите Нур на главный экран и откройте приложение оттуда.');return;}try{const p=await Notification.requestPermission();setPermission(p);if(p!=='granted'){notify(p==='denied'?'Уведомления заблокированы в настройках браузера.':'Разрешение не получено.');return;}setNotificationEnabled(true);save('noor-notifications',true);if(pushInfo?.configured)await syncPush(true);await testNotification();}catch{notify('Установите PWA на главный экран и попробуйте ещё раз.');}}
async function disableNotifications(){setNotificationEnabled(false);save('noor-notifications',false);try{const reg=await navigator.serviceWorker.ready,sub=await reg.pushManager.getSubscription();if(sub){await fetch('/api/push/unsubscribe',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({endpoint:sub.endpoint})});await sub.unsubscribe();}}catch{}setPushStatus('');notify('Уведомления выключены');}
async function searchCity(){if(locationQuery.trim().length<2)return;setLocationBusy(true);setLocationError('');try{const r=await fetch(`https://geocoding-api.open-meteo.com/v1/search?name=${encodeURIComponent(locationQuery.trim())}&count=8&language=ru&format=json`);if(!r.ok)throw Error();const d:any=await r.json();setLocationResults((d.results||[]).map((c:any)=>({name:`${c.name}${c.admin1?', '+c.admin1:''}${c.country?', '+c.country:''}`,latitude:c.latitude,longitude:c.longitude,timezone:c.timezone||'UTC'})));if(!d.results?.length)setLocationError('Город не найден. Попробуйте другое название.');}catch{setLocationError('Поиск недоступен. Выберите город ниже или введите координаты.');}finally{setLocationBusy(false);}}
function choosePlace(p:Place){setPlace(p);setSelectedDay('');setModal('');setLocationResults([]);notify(`Расписание обновлено · ${p.name}`);}
async function locate(){if(!navigator.geolocation){setLocationError('Геолокация недоступна. Выберите город.');return;}setLocationBusy(true);setLocationError('');navigator.geolocation.getCurrentPosition(async pos=>{try{const {latitude,longitude}=pos.coords;const r=await fetch(`https://api.aladhan.com/v1/timings?latitude=${latitude}&longitude=${longitude}&method=3`);if(!r.ok)throw Error();const d:any=await r.json();if(!d.data.meta.timezone)throw Error();choosePlace({name:'Моё местоположение',latitude,longitude,timezone:d.data.meta.timezone});notify(`Геопозиция определена · точность ±${Math.round(pos.coords.accuracy)} м`);}catch{setCoordinates({latitude:pos.coords.latitude.toFixed(5),longitude:pos.coords.longitude.toFixed(5),timezone:Intl.DateTimeFormat().resolvedOptions().timeZone});setLocationError('Координаты получены. Проверьте часовой пояс в ручном вводе и сохраните.');}finally{setLocationBusy(false);}},e=>{setLocationBusy(false);setLocationError(e.code===1?'Доступ к геопозиции запрещён. Выберите город вручную.':'Не удалось определить геопозицию. Выберите город или повторите попытку.');},{enableHighAccuracy:true,timeout:15000,maximumAge:60000});}
function chooseCoordinates(){const lat=+coordinates.latitude,lon=+coordinates.longitude;if(!coordinates.latitude||!coordinates.longitude||!Number.isFinite(lat)||!Number.isFinite(lon)||Math.abs(lat)>90||Math.abs(lon)>180){setLocationError('Широта: от −90 до 90. Долгота: от −180 до 180.');return;}try{new Intl.DateTimeFormat('ru',{timeZone:coordinates.timezone}).format(new Date());}catch{setLocationError('Часовой пояс IANA: например Europe/Moscow.');return;}choosePlace({name:`${lat.toFixed(3)}°, ${lon.toFixed(3)}°`,latitude:lat,longitude:lon,timezone:coordinates.timezone});}
function remember(s:number,a:number,p:number){const value={surah:s,ayah:a,page:p};setPosition(value);save('noor-position',value);}
function openSurah(n:number,a=1){setSurah(n);const ayah=arabic[n-1]?.ayahs.find(x=>x.numberInSurah===a);setPage(ayah?.page||1);setView('quran');history.replaceState(null,'','#quran');remember(n,a,ayah?.page||1);window.scrollTo(0,0);if(a>1)setTimeout(()=>document.getElementById('ayah-'+a)?.scrollIntoView({block:'center'}),200);}
function changePage(n:number){const p=Math.max(1,Math.min(604,n));setPage(p);const s=arabic.find(s=>s.ayahs.some(a=>a.page===p));if(s){setSurah(s.number);const a=s.ayahs.find(a=>a.page===p)!;remember(s.number,a.numberInSurah,p);}window.scrollTo(0,0);}
function toggleBookmark(k:string){setBookmarks(b=>{const v=b.includes(k)?b.filter(x=>x!==k):[...b,k];save('noor-bookmarks',v);return v;});}
function play(n:number){if(playingSurah===n&&audio.current){if(playing){audio.current.pause();setPlaying(false);}else audio.current.play().then(()=>setPlaying(true)).catch(()=>setAudioError('Аудио недоступно. Проверьте интернет.'));return;}audio.current?.pause();const a=new Audio(`https://cdn.islamic.network/quran/audio-surah/128/ar.alafasy/${n}.mp3`);audio.current=a;setPlayingSurah(n);setAudioError('');a.onended=()=>setPlaying(false);a.onerror=()=>{setPlaying(false);setAudioError('Не удалось загрузить аудио. Проверьте интернет.');};a.play().then(()=>setPlaying(true)).catch(()=>setAudioError('Не удалось начать воспроизведение.'));}
async function startCompass(){try{const D=DeviceOrientationEvent as any;if(typeof D.requestPermission==='function'&&(await D.requestPermission())!=='granted'){setCompassStatus('Доступ к датчику запрещён. Ориентируйтесь относительно истинного севера.');return;}let received=false;const listener=(e:DeviceOrientationEvent)=>{const d=e as any;const value=typeof d.webkitCompassHeading==='number'&&d.webkitCompassAccuracy>=0?d.webkitCompassHeading:e.absolute&&e.alpha!==null?(360-e.alpha)%360:null;if(value!==null){received=true;setHeading(value);setCompassStatus('Держите телефон горизонтально, вдали от магнитов и металла.');}};compassCleanup.current?.();window.addEventListener('deviceorientationabsolute',listener,true);window.addEventListener('deviceorientation',listener,true);compassCleanup.current=()=>{window.removeEventListener('deviceorientationabsolute',listener,true);window.removeEventListener('deviceorientation',listener,true);};setCompassStatus('Ожидаем датчик компаса…');setTimeout(()=>{if(!received)setCompassStatus('Датчик абсолютного направления недоступен. Совместите «С» с истинным севером.');},4000);}catch{setCompassStatus('Компас недоступен. Совместите «С» с истинным севером.');}}
async function install(){if(installPrompt.current){await installPrompt.current.prompt();installPrompt.current=null;}else setModal('install');}
async function cacheQuran(){setDownloadBusy(true);setCacheStatus('Сохраняем Коран…');try{const c=await caches.open('noor-content-v1');for(const url of ['/data/arabic.json','/data/russian.json','/fonts/uthmani.ttf','/mushaf/001.svg','/mushaf/002.svg']){const r=await fetch(url);if(!r.ok)throw Error();await c.put(url,r);}setCacheStatus('Весь текст и перевод сохранены. Страницы мусхафа сохраняются при чтении.');notify('Коран сохранён для чтения без интернета');}catch{setCacheStatus('Не удалось завершить сохранение. Проверьте интернет и свободное место.');}finally{setDownloadBusy(false);}}
function exportCalendar(){download(calendar(place,settings),'noor-prayers-30-days.ics','text/calendar;charset=utf-8');notify('Календарь на 30 дней скачан. Импортируйте его в приложение календаря.');}

return <>
<header className="masthead"><button className="brand" aria-label="Нур — на главную" onClick={()=>go('today')}><span className="brand-mark">ن</span><span>нур<span className="brand-dot">.</span></span></button><span className="masthead-center">ВРЕМЯ ДЛЯ ГЛАВНОГО</span><div className="header-actions"><button className="location-label" onClick={()=>setModal('location')}><MapPin size={15}/><span>{place.name.split(',')[0]}</span><ChevronRight size={12}/></button><button className="icon-btn" aria-label="Уведомления" onClick={()=>setModal('notifications')}><Bell size={21}/>{notificationEnabled&&<i className="notification-dot"/>}</button></div></header>
{!online&&<div className="offline-banner"><WifiOff size={14}/>Вы офлайн · сохранённые материалы доступны</div>}
<main className={`main view-${view} ${surah?'reading-active':''}`}>
{view==='today'&&<><div className="page-heading"><div><p className="eyebrow">{new Intl.DateTimeFormat('ru-RU',{timeZone:place.timezone,weekday:'long',day:'numeric',month:'long'}).format(now)}</p><h1>Мир вашему дому<span className="accent-dot">.</span></h1></div><div className="hijri"><span>{hijri}</span><small>По календарю Умм аль-Кура</small></div></div>
<section className="hero" aria-label="Следующий намаз"><img className="hero-image" src="/images/mosque.jpg" alt="Купола и минареты мечети в мягком свете" fetchPriority="high"/><div className="hero-shade"/><div className="hero-top"><Glass className="hero-place" as="button" onClick={()=>setModal('location')}><MapPin size={14}/>{place.name.split(',')[0]}<ChevronRight size={12}/></Glass><span className="hero-arabic" lang="ar" dir="rtl">حَيَّ عَلَى الصَّلَاةِ</span></div><div className="hero-body"><div className="hero-eyebrow"><span className="live-dot"/>СЛЕДУЮЩИЙ НАМАЗ</div><h2>{next?.name||'Время намаза'}</h2><div className="hero-time">{next?formatTime(next.date,place.timezone):'—:—'}<span>{next?.desc}</span></div><Glass className="countdown"><span>Осталось до намаза</span><strong suppressHydrationWarning>{ready?countdown:'—:—:—'}</strong></Glass><div className="hero-buttons"><button className="button button-white" onClick={()=>setModal('notifications')}><BellRing size={17}/>Напомнить мне</button><button className="hero-more" aria-label="К расписанию" onClick={()=>document.getElementById('prayer-schedule')?.scrollIntoView({behavior:'smooth'})}><ArrowDown size={20}/></button></div></div><div className="hero-caption"><p>«Воистину, намаз оберегает<br/>от мерзости и предосудительного»</p><small>КОРАН · 29:45 · ФРАГМЕНТ</small></div></section>
<section className="prayer-section" id="prayer-schedule"><div className="section-heading"><h2>Время намаза</h2><div className="date-control"><button aria-label="Предыдущий день" onClick={()=>setSelectedDay(shiftDay(date,-1))}><ChevronLeft size={17}/></button><label className="date-label"><span>{date===today?'Сегодня':new Intl.DateTimeFormat('ru-RU',{day:'numeric',month:'long'}).format(new Date(date+'T12:00:00'))}</span><input type="date" aria-label="Дата расписания" value={date} onChange={e=>setSelectedDay(e.target.value||today)}/></label><button aria-label="Следующий день" onClick={()=>setSelectedDay(shiftDay(date,1))}><ChevronRight size={17}/></button>{date!==today&&<button className="today-reset" onClick={()=>setSelectedDay('')}>Сегодня</button>}</div></div><div className="prayer-grid">{schedule.map(p=><div className={`prayer-card ${p.id===next?.id&&date===today?'upcoming':''} ${p.date?.getTime()<now.getTime()&&date===today?'past':''}`} key={p.id}><div className="prayer-card-top"><PrayerIcon id={p.id}/>{p.id===next?.id&&date===today?<span className="next-pill">СЛЕДУЮЩИЙ</span>:<span className="prayer-arabic" lang="ar">{p.arabic}</span>}</div><span className="prayer-name">{p.name}</span><strong>{formatTime(p.date,place.timezone)}</strong><span className="prayer-status">{p.id==='sunrise'?'Не является намазом':date===today&&p.date?.getTime()<now.getTime()?<><Check size={11}/>Время прошло</>:p.desc}</span></div>)}</div><p className="calculation-note"><span className="status-dot"/>{METHODS.find(m=>m.id===settings.method)?.name.split(' · ')[0]} · {settings.madhab==='Hanafi'?'Ханафи':'Шафии'} · {place.timezone}<button onClick={()=>go('settings')}>Изменить<ChevronRight size={12}/></button></p></section>
<section className="daily-section"><div className="section-heading"><h2>Ближе к главному</h2><span className="section-caption">Каждый день — с намерением</span></div><div className="discovery-grid"><button className="discovery-card quran-card" onClick={()=>{go('quran');if(position&&arabic.length)openSurah(position.surah,position.ayah);}}><span className="discovery-icon"><BookOpen size={22}/></span><span className="quran-art" lang="ar">القرآن<br/><small>الكريم</small></span><div className="discovery-content"><small>СВЯЩЕННЫЙ КОРАН</small><h3>Слова, которые<br/>освещают сердце</h3><p>{position?`${SURAH_NAMES[position.surah-1]} · аят ${position.ayah}`:'114 сур · перевод и мусхаф'}</p><span className="discovery-link">{position?'Продолжить чтение':'Начать чтение'}<ArrowUpRight size={16}/></span></div></button><button className="discovery-card adhkar-card" onClick={()=>go('adhkar')}><span className="discovery-icon"><Sunrise size={23}/></span><span className="sun-art"/><div className="discovery-content"><small>ПОМНИТЬ И БЛАГОДАРИТЬ</small><h3>Спокойствие<br/>в поминании</h3><p>Утром, вечером и после намаза</p><span className="discovery-link">Читать азкары<ArrowUpRight size={16}/></span></div></button><button className="discovery-card qibla-card" onClick={()=>go('qibla')}><span className="discovery-icon"><Compass size={22}/></span><div className="mini-compass"><i/><span>✦</span><b>⌂</b></div><div className="discovery-content"><small>ВАШЕ НАПРАВЛЕНИЕ</small><h3>Где бы<br/>вы ни были</h3><p>{bearing.toFixed(1)}° к Священной Каабе</p><span className="discovery-link">Найти киблу<ArrowUpRight size={16}/></span></div></button></div></section><section className="daily-verse"><span className="verse-symbol">۞</span><div><small>НАПОМИНАНИЕ СЕРДЦУ</small><p>«Поминайте Меня, и Я буду помнить о вас»</p><span>Коран · 2:152 · фрагмент</span></div><button className="icon-btn" aria-label="Открыть аят 2:152" onClick={()=>{go('quran');if(arabic.length)openSurah(2,152);}}><ArrowUpRight size={22}/></button></section><div className="install-strip"><span className="app-icon-small">ن</span><div><strong>Нур. Всегда рядом.</strong><span>Добавьте приложение на главный экран</span></div><button className="text-button" onClick={install}>Установить<ArrowUpRight size={14}/></button></div></>}

{view==='quran'&&!surah&&<><div className="page-heading"><div><p className="eyebrow">ЧИТАЙТЕ С СЕРДЦЕМ</p><h1>Священный Коран<span className="accent-dot">.</span></h1></div><button className="subtle-button" onClick={cacheQuran} disabled={downloadBusy}><Download size={16}/>{downloadBusy?'Сохраняем…':'Читать офлайн'}</button></div><section className="quran-banner"><div><span className="eyebrow">114 СУР · 30 ДЖУЗОВ · 604 СТРАНИЦЫ</span><h2>Свет на каждой странице</h2><p>Арабский текст, перевод смыслов Кулиева<br/>и страницы Мединского мусхафа.</p>{position&&<button className="button button-white" onClick={()=>openSurah(position.surah,position.ayah)}><Bookmark size={16}/>Продолжить · {SURAH_NAMES[position.surah-1]}</button>}</div><span lang="ar" className="banner-calligraphy">القرآن الكريم</span></section><div className="quran-tools"><label className="search-field"><Search size={18}/><input placeholder="Найти суру по названию или номеру" value={query} onChange={e=>setQuery(e.target.value)}/>{query&&<button aria-label="Очистить поиск" onClick={()=>setQuery('')}><X size={17}/></button>}</label><span className="surah-total">{list.length} сур</span></div>{cacheStatus&&<p className="inline-note">{cacheStatus}</p>}{bookmarks.length>0&&<details className="bookmark-list"><summary><Bookmark size={16}/>Закладки · {bookmarks.length}</summary><div>{bookmarks.map(k=>{const [s,a]=k.split(':').map(Number);return <button key={k} onClick={()=>openSurah(s,a)}>{SURAH_NAMES[s-1]} · {a}<ChevronRight size={14}/></button>;})}</div></details>}{loading&&<div className="empty-state"><LoaderCircle className="spin"/>Открываем Коран…</div>}{dataError&&<div className="empty-state"><WifiOff/>{dataError}<button className="button" onClick={loadQuran}>Повторить</button></div>}<div className="surah-grid">{list.map(s=><button className="surah-item" key={s.number} onClick={()=>openSurah(s.number)}><span className="surah-number"><span>{s.number}</span></span><span className="surah-info"><strong>{SURAH_NAMES[s.number-1]}</strong><small>{SURAH_MEANINGS[s.number-1]} · {s.ayahs.length} аятов</small></span><span className="surah-arabic" lang="ar" dir="rtl">{s.name.replace(/^سُورَةُ\s*/,'')}</span><ChevronRight size={15}/></button>)}</div>{!loading&&!dataError&&list.length===0&&<div className="empty-state"><Search/>Сура не найдена<button className="text-button" onClick={()=>setQuery('')}>Сбросить поиск</button></div>}<p className="source-note">Хафс от Асыма · текст: Tanzil / Al Quran Cloud · перевод: Э. Кулиев<br/>Каллиграфические страницы: Batoul Apps Quran SVG · Мединский мусхаф</p></>}
{view==='quran'&&surah&&<div className={`reader reader-${settings.readingTheme}`}><div className="reader-top"><button className="back-button" onClick={()=>{setSurah(null);window.scrollTo(0,0);}}><ArrowLeft size={20}/><span>Все суры</span></button><div className="reader-title"><strong>{SURAH_NAMES[(mode==='book'?pageMeta[0]?.surah||surah:surah)-1]}</strong><small>{mode==='book'?`Джуз ${pageMeta[0]?.juz||1} · Страница ${page} из 604`:`Сура ${surah} · ${current?.ayahs.length||0} аятов`}</small></div><button className="icon-btn" aria-label="Настройки чтения" onClick={()=>go('settings')}><Settings2 size={20}/></button></div><div className="reader-toolbar"><Glass className="segmented"><button className={mode==='translation'?'selected':''} onClick={()=>setMode('translation')}><BookOpen size={15}/>С переводом</button><button className={mode==='book'?'selected':''} onClick={()=>setMode('book')}>Мусхаф</button></Glass><div className="reading-themes">{['paper','sepia','night'].map(t=><button key={t} className={`theme-dot ${t} ${settings.readingTheme===t?'active':''}`} aria-label={t==='paper'?'Светлая бумага':t==='sepia'?'Тёплая бумага':'Ночное чтение'} onClick={()=>update('readingTheme',t)}/>)}</div></div>{mode==='translation'?<><div className="reader-surah-heading"><span lang="ar" dir="rtl">{current?.name}</span><p>{SURAH_MEANINGS[surah-1]}</p><button className="audio-button" onClick={()=>play(surah)}>{playing&&playingSurah===surah?<Pause size={17}/>:<Play size={17}/>}Мишари Рашид аль-Афаси</button>{audioError&&<small className="error-text">{audioError}</small>}</div>{surah!==1&&surah!==9&&<p className="bismillah" lang="ar" dir="rtl">بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ</p>}<div className="ayahs">{current?.ayahs.map((a,i)=><article id={'ayah-'+a.numberInSurah} className={`ayah ${bookmarks.includes(`${surah}:${a.numberInSurah}`)?'bookmarked':''}`} key={a.number}><div className="ayah-meta"><span>{surah}:{a.numberInSurah}</span><div><button aria-label={`Продолжить с аята ${a.numberInSurah}`} onClick={()=>{remember(surah,a.numberInSurah,a.page);notify('Место чтения сохранено');}}><CheckCircle2 size={16}/></button><button aria-label={`Закладка на аяте ${a.numberInSurah}`} aria-pressed={bookmarks.includes(`${surah}:${a.numberInSurah}`)} onClick={()=>toggleBookmark(`${surah}:${a.numberInSurah}`)}><Bookmark size={16} fill={bookmarks.includes(`${surah}:${a.numberInSurah}`)?'currentColor':'none'}/></button></div></div><p className="arabic-text" style={{fontSize:settings.arabicSize}} lang="ar" dir="rtl">{a.numberInSurah===1&&surah!==1&&surah!==9?a.text.replace(arabic[0].ayahs[0].text.replace(/\ufeff/g,''),'').trim():a.text}<span className="ayah-end"> ﴿{a.numberInSurah.toLocaleString('ar-EG')}﴾</span></p><p className="ayah-translation">{russian[surah-1]?.ayahs[i]?.text}</p></article>)}</div><div className="surah-navigation"><button className="subtle-button" disabled={surah===1} onClick={()=>openSurah(surah-1)}><ChevronLeft size={16}/>Предыдущая сура</button><button className="subtle-button" disabled={surah===114} onClick={()=>openSurah(surah+1)}>Следующая сура<ChevronRight size={16}/></button></div></>:<><div className={`mushaf-page ${page<=2?'opening-page':''}`}><div className="mushaf-header"><span>{pageMeta[0]?.name||'القرآن الكريم'}</span><span>الجزء {(pageMeta[0]?.juz||1).toLocaleString('ar-EG')}</span></div>{bookLoading&&!bookError&&<div className="mushaf-loader"><LoaderCircle className="spin"/>Открываем страницу…</div>}{!bookError&&<img key={page} className="mushaf-image" src={page<=2?`/mushaf/${String(page).padStart(3,'0')}.svg`:`/api/mushaf/${page}`} alt={`Страница ${page} Мединского мусхафа, Хафс от Асыма`} onLoad={()=>setBookLoading(false)} onError={()=>{setBookError(true);setBookLoading(false);}}/>}{bookError&&<div className="empty-state"><WifiOff/><p>Страница ещё не сохранена.<br/>Для первой загрузки нужен интернет.</p><button className="subtle-button" onClick={()=>{setBookError(false);setBookLoading(true);}}>Повторить</button></div>}<span className="mushaf-page-number">﴿ {page.toLocaleString('ar-EG')} ﴾</span></div><Glass className="page-turner"><button aria-label="Предыдущая страница" disabled={page===1} onClick={()=>changePage(page-1)}><ChevronLeft size={21}/></button><label>Страница<input aria-label="Номер страницы мусхафа" type="number" min={1} max={604} value={pageInput} onChange={e=>setPageInput(e.target.value)} onBlur={()=>{const p=+pageInput;if(Number.isInteger(p)&&p>=1&&p<=604)changePage(p);else setPageInput(String(page));}} onKeyDown={e=>{if(e.key==='Enter')e.currentTarget.blur();}}/><span>из 604</span></label><button aria-label="Следующая страница" disabled={page===604} onClick={()=>changePage(page+1)}><ChevronRight size={21}/></button></Glass><p className="reader-help">Подлинная каллиграфия · исходное расположение аятов · 604 страницы</p></>}</div>}

{view==='adhkar'&&<><div className="page-heading"><div><p className="eyebrow">ПОМНИТЬ И БЛАГОДАРИТЬ</p><h1>Покой в поминании<span className="accent-dot">.</span></h1></div><span className="page-arabic" lang="ar">ذكر الله</span></div><div className="adhkar-intro"><p>«Поминанием Аллаха утешаются сердца»</p><span>Коран · 13:28 · фрагмент</span></div><div className="adhkar-tools"><Glass className="segmented adhkar-tabs">{[{id:'morning',name:'Утренние',icon:Sunrise},{id:'evening',name:'Вечерние',icon:Moon},{id:'prayer',name:'После намаза',icon:Sparkles}].map(g=><button className={group===g.id?'selected':''} key={g.id} onClick={()=>{setGroup(g.id);setExpanded(null);}}><g.icon size={17}/>{g.name}</button>)}</Glass><button className="icon-btn" aria-label="Сбросить счётчики" onClick={()=>{setCounts({});notify('Счётчики обнулены');}}><RotateCcw size={18}/></button></div>{group==='prayer'&&<><div className="prayer-adhkar-context"><label htmlFor="after-prayer-select">После какого намаза?</label><select id="after-prayer-select" value={afterPrayer} onChange={e=>setAfterPrayer(e.target.value)}><option value="Fajr">Фаджр · утренний</option><option value="Dhuhr">Зухр · полуденный</option><option value="Asr">Аср · послеполуденный</option><option value="Maghrib">Магриб · вечерний</option><option value="Isha">Иша · ночной</option></select></div><p className="adhkar-context-note">{ADHKAR_PRAYER_NOTE} Счётчики ведутся отдельно для каждого намаза.</p></>}<div className="adhkar-progress"><span>{completed===dhikrs.length?'Все азкары прочитаны. Пусть Аллах примет.':`${completed} из ${dhikrs.length} азкаров прочитано`}</span><div><i style={{width:`${completed/dhikrs.length*100}%`}}/></div><small>Счётчики сохраняются отдельно для каждой группы и обновляются ежедневно.</small></div><div className="dhikr-list">{dhikrs.map((d,i)=><article className={`dhikr-card ${(counts[d.id]||0)>=d.target?'complete':''}`} key={d.id}><div className="dhikr-heading"><span className="dhikr-index">{String(i+1).padStart(2,'0')}</span><div><h2>{d.title}</h2><small>{d.source}</small></div><span className="repeat-pill">{d.target} {d.target===3||d.target===33?'раза':'раз'}</span></div><p className="arabic-text" style={{fontSize:settings.arabicSize}} lang="ar" dir="rtl">{d.arabic}</p><p className="dhikr-translation">{d.translation}</p><button className="transliteration-toggle" onClick={()=>setExpanded(expanded===d.id?null:d.id)}>{expanded===d.id?'Скрыть транскрипцию':'Транскрипция'}<ChevronRight size={13}/></button>{expanded===d.id&&<p className="transliteration">{d.transliteration}</p>}<div className="dhikr-footer"><span>{(counts[d.id]||0)>=d.target?'Прочитано':'Нажмите после прочтения'}</span><button className="dhikr-counter" aria-label={`Счётчик ${d.title}: ${counts[d.id]||0} из ${d.target}`} onClick={()=>{if((counts[d.id]||0)<d.target){setCounts(c=>({...c,[d.id]:Math.min(d.target,(c[d.id]||0)+1)}));navigator.vibrate?.(15);}}}>{(counts[d.id]||0)>=d.target?<Check size={20}/>:<Plus size={18}/>}<strong>{counts[d.id]||0}<span> / {d.target}</span></strong></button></div></article>)}</div><p className="source-note">Избранные азкары из Корана и достоверных хадисов.<br/>Перевод передаёт смысл. Транскрипция не заменяет изучение арабского произношения.</p></>}

{view==='qibla'&&<><div className="page-heading"><div><p className="eyebrow">ОДНО НАПРАВЛЕНИЕ. МИЛЛИОНЫ СЕРДЕЦ.</p><h1>Навстречу Каабе<span className="accent-dot">.</span></h1></div><button className="subtle-button" onClick={()=>setModal('location')}><MapPin size={15}/>{place.name.split(',')[0]}</button></div><section className="qibla-panel"><div className="qibla-glow"/><div className="qibla-label"><span className="live-dot"/>{heading!==null?'КОМПАС АКТИВЕН':'НАПРАВЛЕНИЕ ОТ ИСТИННОГО СЕВЕРА'}</div><div className="compass-wrap"><div className="compass-dial" style={{transform:`rotate(${heading!==null?-heading:0}deg)`}}><div className="compass-ticks">{Array.from({length:72},(_,i)=><i key={i} className={i%6===0?'major':''} style={{transform:`translateX(-50%) rotate(${i*5}deg)`}}/>)}</div><span className="north">С</span><span className="east">В</span><span className="south">Ю</span><span className="west">З</span><div className="qibla-needle" style={{transform:`rotate(${bearing}deg)`}}><div className="kaaba-marker"><svg viewBox="0 0 40 40" aria-label="Кааба"><path d="M6 12 23 6 35 12 18 18Z" fill="#cbb380"/><path d="M6 12 18 18 18 35 6 28Z" fill="#272824"/><path d="M18 18 35 12 35 28 18 35Z" fill="#0f1717"/><path d="M6 17 18 23 35 17" fill="none" stroke="#d1b878" strokeWidth="3"/></svg></div><div className="needle-top"/><div className="needle-bottom"/></div></div><div className="compass-center"><span>КИБЛА</span><strong>{bearing.toFixed(1)}<small>°</small></strong><span>{heading!==null?`Телефон: ${heading.toFixed(0)}°`:'от истинного севера'}</span></div><div className="compass-north-mark"/></div><p className="qibla-description">Одно намерение.<br/><strong>Где бы вы ни находились.</strong></p><div className="qibla-metrics"><div><span>До Священной Каабы</span><strong>{distanceToMecca(place).toLocaleString('ru-RU')} <small>км</small></strong></div><i/><div><span>Ваше местоположение</span><strong>{place.name.split(',')[0]}</strong></div></div><button className="button button-white" onClick={startCompass}><Navigation size={17}/>Включить компас</button>{compassStatus&&<p className="compass-status" role="status">{compassStatus}</p>}</section><div className="qibla-tip"><CircleHelp size={20}/><div><strong>Как найти точное направление</strong><p>Разрешите геолокацию и доступ к датчику. Положите телефон горизонтально, вдали от магнитов. Для калибровки плавно опишите телефоном восьмёрку. Без датчика совместите «С» с истинным севером. Показания магнитного датчика могут отличаться от истинного севера — проверьте направление по карте.</p><a href={`https://www.google.com/maps/dir/?api=1&origin=${place.latitude},${place.longitude}&destination=21.422487,39.826206`} target="_blank" rel="noreferrer">Показать на карте<ExternalLink size={13}/></a></div></div></>}

{view==='settings'&&<><div className="page-heading"><div><p className="eyebrow">ВАШ ЛИЧНЫЙ РИТМ</p><h1>Всё по-вашему<span className="accent-dot">.</span></h1></div><span className="settings-version">Нур · 1.0</span></div><div className="settings-grid"><section className="settings-card"><div className="settings-heading"><Sun size={21}/><h2>Намаз и местоположение</h2></div><button className="settings-location" onClick={()=>setModal('location')}><MapPin size={19}/><span><strong>{place.name}</strong><small>{place.latitude.toFixed(4)}°, {place.longitude.toFixed(4)}° · {place.timezone}</small></span><ChevronRight size={16}/></button><label className="setting-row"><span>Метод расчёта<small>Углы сумерек для Фаджра и Иша</small></span><select value={settings.method} onChange={e=>update('method',e.target.value)}>{METHODS.map(m=><option key={m.id} value={m.id}>{m.name}</option>)}</select></label><label className="setting-row"><span>Мазхаб<small>Определяет время Асра</small></span><select value={settings.madhab} onChange={e=>update('madhab',e.target.value)}><option value="Shafi">Шафии / Малики / Ханбали</option><option value="Hanafi">Ханафи</option></select></label><div className="setting-row"><span>Поправка времени<small>Для пяти намазов, в минутах</small></span><div className="stepper"><button aria-label="Уменьшить поправку" onClick={()=>update('adjustment',Math.max(-30,settings.adjustment-1))}><Minus size={15}/></button><output>{settings.adjustment>0?'+':''}{settings.adjustment}</output><button aria-label="Увеличить поправку" onClick={()=>update('adjustment',Math.min(30,settings.adjustment+1))}><Plus size={15}/></button></div></div><p className="settings-note">На высоких широтах используется правило 1/7 ночи. Сверьте метод и поправки с расписанием местной мечети. Дата хиджры может отличаться от местного наблюдения луны.</p></section><section className="settings-card"><div className="settings-heading"><Bell size={21}/><h2>Напоминания</h2></div><div className="setting-row"><span>Уведомления о намазе<small>{notificationEnabled?'Включены на этом устройстве':'Для пяти ежедневных намазов'}</small></span><button className={`switch ${notificationEnabled?'on':''}`} role="switch" aria-checked={notificationEnabled} aria-label="Уведомления о намазе" onClick={()=>notificationEnabled?disableNotifications():enableNotifications()}><i/></button></div><label className="setting-row"><span>Когда напоминать</span><select value={settings.reminder} onChange={e=>update('reminder',+e.target.value)}><option value={0}>В момент наступления</option><option value={5}>За 5 минут</option><option value={10}>За 10 минут</option><option value={15}>За 15 минут</option></select></label><div className="notification-prayers">{PRAYERS.filter(p=>p.id!=='sunrise').map(p=><label key={p.id}><input type="checkbox" checked={settings.enabledPrayers.includes(p.id)} onChange={()=>update('enabledPrayers',settings.enabledPrayers.includes(p.id)?settings.enabledPrayers.filter(x=>x!==p.id):[...settings.enabledPrayers,p.id])}/><span>{p.name}</span></label>)}</div><div className="settings-buttons"><button className="subtle-button" onClick={()=>permission==='granted'?testNotification():enableNotifications()}><BellRing size={15}/>Проверить</button><button className="subtle-button" onClick={exportCalendar}><CalendarDays size={15}/>Календарь на 30 дней</button></div><p className="settings-note">{pushInfo?.configured&&pushInfo.scheduler?'Web Push доставляет напоминания при закрытом приложении. Время доставки зависит от сети, операционной системы и серверного планировщика.':'Уведомления доступны в открытом приложении. Для фоновой доставки подключается Web Push. Календарь с сигналами работает отдельно.'} На iPhone установите PWA на главный экран (iOS 16.4+).</p>{pushStatus&&<p className="inline-note">{pushStatus}</p>}</section><section className="settings-card"><div className="settings-heading"><BookOpen size={21}/><h2>Комфортное чтение</h2></div><div className="setting-row"><span>Арабский шрифт<small>В режиме перевода и в азкарах</small></span><div className="stepper"><button aria-label="Уменьшить арабский шрифт" onClick={()=>update('arabicSize',Math.max(24,settings.arabicSize-2))}><Minus size={15}/></button><output>{settings.arabicSize}</output><button aria-label="Увеличить арабский шрифт" onClick={()=>update('arabicSize',Math.min(52,settings.arabicSize+2))}><Plus size={15}/></button></div></div><p className="font-preview" lang="ar" dir="rtl" style={{fontSize:settings.arabicSize}}>بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ</p><label className="setting-row"><span>Бумага для чтения</span><select value={settings.readingTheme} onChange={e=>update('readingTheme',e.target.value)}><option value="paper">Светлая</option><option value="sepia">Тёплая</option><option value="night">Ночная</option></select></label><button className="subtle-button wide" disabled={downloadBusy} onClick={cacheQuran}><Download size={16}/>{downloadBusy?'Сохраняем…':'Сохранить весь текст Корана офлайн'}</button>{cacheStatus&&<p className="inline-note">{cacheStatus}</p>}<p className="settings-note">114 сур и перевод — около 4 МБ. Страницы мусхафа сохраняются при открытии. Для аудио нужен интернет.</p></section><section className="settings-card"><div className="settings-heading"><Sparkles size={21}/><h2>Оформление и приложение</h2></div><label className="setting-row"><span>Внешний вид</span><select value={settings.theme} onChange={e=>update('theme',e.target.value)}><option value="dark">Тёмный</option><option value="light">Светлый</option></select></label><div className="setting-row"><span>Меньше прозрачности<small>Плотные поверхности вместо стекла</small></span><button role="switch" aria-checked={settings.reducedGlass} aria-label="Меньше прозрачности" className={`switch ${settings.reducedGlass?'on':''}`} onClick={()=>update('reducedGlass',!settings.reducedGlass)}><i/></button></div><button className="settings-location" onClick={install}><Download size={19}/><span><strong>Установить Нур</strong><small>Всегда рядом на главном экране</small></span><ChevronRight size={16}/></button><div className="privacy-note"><Heart size={18}/><div><strong>Пространство без лишнего</strong><p>Без рекламы и аналитики. Настройки и закладки хранятся на устройстве. Поиск города: Open-Meteo. Часовой пояс по геопозиции: Aladhan. При включении Web Push координаты и настройки расчёта хранятся на сервере для отправки напоминаний.</p></div></div><a className="source-link" href="https://github.com/maga17mm-hub/noor-prayer-pwa" target="_blank" rel="noreferrer">Открытый исходный код<ArrowUpRight size={14}/></a></section></div></>}
</main><footer className="site-footer"><span className="footer-brand">нур.</span><span>Меньше суеты. Больше смысла.</span><span>С заботой о вашем времени</span></footer><div className="navigation-wrap"><Glass className="bottom-nav" as="nav" aria-label="Основная навигация">{NAV.map(n=><button key={n.id} className={view===n.id?'active':''} aria-current={view===n.id?'page':undefined} onClick={()=>go(n.id as View)}><n.icon size={22} strokeWidth={view===n.id?2:1.7}/><span>{n.name}</span></button>)}</Glass></div>
{playingSurah&&<Glass className="mini-player"><button className="icon-btn" aria-label={playing?'Пауза':'Продолжить аудио'} onClick={()=>play(playingSurah)}>{playing?<Pause size={18}/>:<Play size={18}/>}</button><div><strong>{SURAH_NAMES[playingSurah-1]}</strong><small>Мишари аль-Афаси</small></div><button className="icon-btn" aria-label="Закрыть плеер" onClick={()=>{audio.current?.pause();setPlaying(false);setPlayingSurah(null);}}><X size={17}/></button></Glass>}
{toast&&<div className="toast" role="status"><CheckCircle2 size={18}/>{toast}<button aria-label="Закрыть сообщение" onClick={()=>setToast('')}><X size={15}/></button></div>}
{modal&&<div className="modal-backdrop" onClick={()=>setModal('')}><section className={`modal ${modal}-modal`} role="dialog" aria-modal="true" aria-label={modal==='location'?'Ваше местоположение':modal==='install'?'Установить Нур':'Напоминания'} onClick={e=>e.stopPropagation()}><button className="modal-close icon-btn" aria-label="Закрыть окно" onClick={()=>setModal('')}><X size={21}/></button>
{modal==='location'&&<><div className="modal-heading"><p className="eyebrow">ТОЧКА ОТСЧЁТА</p><h2>Где вы сейчас?</h2></div><button className="geolocation-button" disabled={locationBusy} onClick={locate}>{locationBusy?<LoaderCircle size={20} className="spin"/>:<LocateFixed size={20}/>}Определить моё местоположение</button><p className="privacy-caption">Координаты нужны для расчёта. Часовой пояс определяет Aladhan.</p><form className="search-field" onSubmit={e=>{e.preventDefault();searchCity();}}><Search size={18}/><input autoFocus placeholder="Найти город" value={locationQuery} onChange={e=>setLocationQuery(e.target.value)}/><button className="search-submit" type="submit" disabled={locationBusy} aria-label="Искать город"><ArrowUpRight size={18}/></button></form>{locationError&&<p className="error-text" role="alert">{locationError}</p>}<div className="location-results">{!locationResults.length&&<small>БЫСТРЫЙ ВЫБОР</small>}{(locationResults.length?locationResults:[DEFAULT_PLACE,{name:'Махачкала',latitude:42.9849,longitude:47.5047,timezone:'Europe/Moscow'},{name:'Грозный',latitude:43.3178,longitude:45.6981,timezone:'Europe/Moscow'},{name:'Казань',latitude:55.7887,longitude:49.1221,timezone:'Europe/Moscow'},{name:'Стамбул',latitude:41.0082,longitude:28.9784,timezone:'Europe/Istanbul'},{name:'Мекка',latitude:21.4225,longitude:39.8262,timezone:'Asia/Riyadh'}]).map((p,i)=><button key={i} onClick={()=>choosePlace(p)}><MapPin size={16}/><span>{p.name}<small>{locationResults.length>0?p.timezone:''}</small></span>{p.name===place.name?<Check size={16}/>:<ChevronRight size={16}/>}</button>)}</div><details className="coordinate-details"><summary>Ввести координаты вручную</summary><div className="coordinate-inputs"><label>Широта<input inputMode="decimal" value={coordinates.latitude} placeholder="55.7558" onChange={e=>setCoordinates(c=>({...c,latitude:e.target.value}))}/></label><label>Долгота<input inputMode="decimal" value={coordinates.longitude} placeholder="37.6173" onChange={e=>setCoordinates(c=>({...c,longitude:e.target.value}))}/></label><label className="full">Часовой пояс IANA<input value={coordinates.timezone} onChange={e=>setCoordinates(c=>({...c,timezone:e.target.value}))}/></label><button className="button wide" onClick={chooseCoordinates}>Сохранить координаты</button></div></details></>}
{modal==='install'&&<><span className="app-icon-large">ن</span><h2>Нур. Всегда рядом.</h2><p>Открывайте приложение одним касанием.</p><ol><li><span>1</span><div>Откройте сайт в <strong>Safari на iPhone</strong><small>На Android — в Chrome</small></div></li><li><span>2</span><div>Нажмите <strong>«Поделиться»</strong> <Share size={16}/><small>На Android — меню ⋮</small></div></li><li><span>3</span><div>Выберите <strong>«На экран “Домой”»</strong><small>На Android — «Установить приложение»</small></div></li></ol><button className="button button-white wide" onClick={()=>setModal('')}>Понятно</button></>}
{modal==='notifications'&&<><div className="notification-illustration"><BellRing size={36} strokeWidth={1.3}/></div><p className="eyebrow">НЕ ПРОПУСТИТЬ ГЛАВНОЕ</p><h2>Время остановиться.<br/>И обратиться к Нему.</h2><p>{pushInfo?.configured?'Разрешите push-уведомления — Нур напомнит о намазе, даже когда приложение закрыто.':'Включите напоминания о времени намаза. Для фоновой отправки подключается сервер.'}</p><button className="button button-white wide" onClick={notificationEnabled?testNotification:enableNotifications}><BellRing size={17}/>{notificationEnabled?'Тестовое уведомление':'Разрешить уведомления'}</button><button className="subtle-button wide" onClick={exportCalendar}><CalendarDays size={17}/>Добавить 30 дней в календарь</button>{pushStatus&&<p className="inline-note">{pushStatus}</p>}{permission==='denied'&&<p className="error-text">Разрешите уведомления в настройках сайта или браузера.</p>}<p className="privacy-caption">На iPhone установите Нур на главный экран, откройте приложение и разрешите уведомления. Требуется iOS 16.4+.</p><button className="text-button centered" onClick={()=>{setModal('');go('settings');}}>Настроить напоминания<ChevronRight size={14}/></button></>}
</section></div>}</>;
}
